function s(t){return{data:t,message:"Datos simulados cargados correctamente",success:!0,timestamp:new Date().toISOString()}}function c(t,n=0,e=10){let o=n*e;return{content:t.slice(o,o+e),pageNumber:n,pageSize:e,totalElements:t.length,totalPages:Math.max(1,Math.ceil(t.length/e)),first:n===0,last:o+e>=t.length}}function r(t,n=0,e=10){let o=n*e;return{content:t.slice(o,o+e),totalElements:t.length,totalPages:Math.max(1,Math.ceil(t.length/e)),number:n,size:e}}export{s as a,c as b,r as c};
